<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Booking', href: '/owner/bookings' }, { title: 'Detail booking', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';

    type Booking = { id: number; status: string; property: { id: number; name: string }; room: { id: number; code: string }; resident: { id: number; full_name: string; whatsapp_number: string }; planned_start_date: string; planned_end_exclusive: string; agreed_monthly_rent_rupiah: number; check_in_deadline_at: string | null; notes: string | null };
    type DepositAccount = { id: number; required_amount_rupiah: number; booking_id: number | null; tenancy_id: number | null } | null;
    let { booking, deposit_account, tenancy, actions, grace_extension_idempotency_key }: { booking: Booking; deposit_account: DepositAccount; tenancy: { id: number; status: string } | null; actions: { can_confirm: boolean; can_cancel: boolean; can_extend_grace: boolean; can_check_in: boolean }; grace_extension_idempotency_key: string } = $props();
    let graceExtensionIdempotencyKey = $state('');

    $effect(() => {
        if (!graceExtensionIdempotencyKey) {
            graceExtensionIdempotencyKey = grace_extension_idempotency_key;
        }
    });

    const labels: Record<string, string> = { pending: 'Menunggu', confirmed: 'Dikonfirmasi', checked_in: 'Sudah check-in', cancelled: 'Dibatalkan', no_show: 'Tidak hadir' };
    const rupiah = (amount: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(amount);

    function rotateGraceExtensionIdempotencyKey() {
        graceExtensionIdempotencyKey = crypto.randomUUID();
    }
</script>

<AppHead title={`Booking ${booking.id}`} />
<main class="mx-auto w-full max-w-5xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">{booking.property.name} · Kamar {booking.room.code}</p><h1 class="text-3xl font-semibold tracking-tight">Booking #{booking.id}</h1><p class="text-sm text-muted-foreground">Status: {labels[booking.status] ?? booking.status}</p></div><Link href="/owner/bookings" class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Daftar booking</Link></header>
    <section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Penyewa</p><Link href={`/owner/residents/${booking.resident.id}`} class="mt-2 inline-block font-medium underline-offset-4 hover:underline">{booking.resident.full_name}</Link><p class="mt-1 text-sm text-muted-foreground">{booking.resident.whatsapp_number}</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Periode booking</p><p class="mt-2 font-medium">{booking.planned_start_date}</p><p class="text-sm text-muted-foreground">Kamar tersedia kembali {booking.planned_end_exclusive}</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Tarif sewa bulanan</p><p class="mt-2 text-xl font-semibold">{rupiah(booking.agreed_monthly_rent_rupiah)}</p><p class="text-sm text-muted-foreground">Snapshot kesepakatan</p></article></section>
    <section class="grid gap-4 sm:grid-cols-2"><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Batas check-in</h2>{#if booking.check_in_deadline_at}<p class="mt-2">{new Intl.DateTimeFormat('id-ID', { dateStyle: 'full', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(booking.check_in_deadline_at))}</p>{:else}<p class="mt-2 text-sm text-muted-foreground">Batas no-show dibuat saat booking dikonfirmasi.</p>{/if}<p class="mt-2 text-xs text-muted-foreground">Grace period berlangsung sampai akhir hari kalender berikutnya setelah tanggal rencana masuk.</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Deposit jaminan</h2><p class="mt-2">{deposit_account ? rupiah(deposit_account.required_amount_rupiah) : 'Belum ditetapkan'}</p><p class="mt-1 text-xs text-muted-foreground">Deposit tetap menjadi kewajiban yang sama setelah booking menjadi tenancy.</p></article></section>
    {#if booking.notes}<section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Catatan</h2><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{booking.notes}</p></section>{/if}
    {#if tenancy}<section class="flex flex-wrap items-center justify-between gap-3 rounded-xl border bg-muted/30 p-5"><div><h2 class="font-semibold">Tenancy terkait</h2><p class="text-sm text-muted-foreground">Status: {tenancy.status}</p></div><Link href={`/owner/tenancies/${tenancy.id}`} class="text-sm font-medium text-primary underline-offset-4 hover:underline">Lihat masa sewa</Link></section>{/if}
    <section class="space-y-4"><h2 class="text-lg font-semibold">Tindakan booking</h2>
        {#if actions.can_confirm}<Form action={`/owner/bookings/${booking.id}/confirm`} method="post" class="space-y-3 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Konfirmasi booking</h3><p class="text-sm text-muted-foreground">Kamar akan ditahan setelah server memeriksa ulang konflik jadwal.</p></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya mengonfirmasi kesepakatan booking ini.</span></label><InputError message={errors.booking} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Memeriksa…' : 'Konfirmasi booking'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_check_in}<Form action={`/owner/bookings/${booking.id}/check-in`} method="post" class="space-y-4 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Check-in dari booking</h3><p class="text-sm text-muted-foreground">Check-in menghubungkan booking dengan tenancy dan menerbitkan invoice pertama satu kali.</p></div><div class="space-y-2"><label for="actual_start_date" class="text-sm font-medium">Tanggal check-in aktual</label><Input id="actual_start_date" name="actual_start_date" type="date" required /><InputError message={errors.actual_start_date} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya mencatat check-in penyewa.</span></label><InputError message={errors.booking} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Catat check-in'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_extend_grace}<Form action={`/owner/bookings/${booking.id}/extend-grace-period`} method="post" onSuccess={rotateGraceExtensionIdempotencyKey} class="space-y-4 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Perpanjang grace period</h3><p class="text-sm text-muted-foreground">Perpanjangan tidak mengubah tanggal rencana masuk dan tidak dapat dilakukan setelah batas expiry.</p></div><input type="hidden" name="idempotency_key" bind:value={graceExtensionIdempotencyKey} /><div class="space-y-2"><label for="new_deadline_at" class="text-sm font-medium">Batas check-in baru</label><Input id="new_deadline_at" name="new_deadline_at" type="datetime-local" required /><InputError message={errors.new_deadline_at} /></div><div class="space-y-2"><label for="reason" class="text-sm font-medium">Alasan perubahan</label><textarea id="reason" name="reason" rows={2} required maxlength={500} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><div class="flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Menyimpan…' : 'Simpan batas baru'}</Button></div>{/snippet}</Form>{/if}
        {#if actions.can_cancel}<Form action={`/owner/bookings/${booking.id}/cancel`} method="post" class="space-y-3 rounded-xl border border-amber-300/60 bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Batalkan booking</h3><p class="text-sm text-muted-foreground">Aplikasi tidak otomatis mengembalikan atau menghanguskan deposit. Penyelesaian dilakukan pemilik dan dicatat terpisah.</p></div><div class="space-y-2"><label for="cancel_reason" class="text-sm font-medium">Alasan</label><textarea id="cancel_reason" name="reason" rows={2} maxlength={500} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya memahami booking dibatalkan dan tidak lagi menahan kamar.</span></label><InputError message={errors.booking} /><div class="flex justify-end"><Button type="submit" variant="destructive" disabled={processing}>{processing ? 'Membatalkan…' : 'Batalkan booking'}</Button></div>{/snippet}</Form>{/if}
        {#if !actions.can_confirm && !actions.can_check_in && !actions.can_extend_grace && !actions.can_cancel}<p class="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">Tidak ada tindakan yang tersedia untuk status booking ini.</p>{/if}
    </section>
</main>
